                    "code": "import numpy as np\n\n# Proyek Mandiri: Mini Causal Decoder Transformer Lengkap (NumPy murni)\nclass MiniLLMDecoder:\n    def __init__(self, vocab_size=32, d_model=16, d_ff=42):\n        self.vocab_size = vocab_size\n        self.d_model = d_model\n        self.d_ff = d_ff\n        np.random.seed(42)\n        \n        # 1. Token Embeddings\n        self.embed = np.random.randn(vocab_size, d_model) * 0.1\n        # 2. Attention Weights (No-Bias)\n        self.W_q = np.random.randn(d_model, d_model) * 0.1\n        self.W_k = np.random.randn(d_model, d_model) * 0.1\n        self.W_v = np.random.randn(d_model, d_model) * 0.1\n        self.W_o = np.random.randn(d_model, d_model) * 0.1\n        # 3. SwiGLU FFN Weights (No-Bias)\n        self.W_gate = np.random.randn(d_ff, d_model) * 0.1\n        self.W_up   = np.random.randn(d_ff, d_model) * 0.1\n        self.W_down = np.random.randn(d_model, d_ff) * 0.1\n        # 4. Unembedding Matrix\n        self.W_u = np.random.randn(vocab_size, d_model) * 0.1\n        \n    def rms_norm(self, x, eps=1e-6):\n        return x / np.sqrt(np.mean(x ** 2, axis=-1, keepdims=True) + eps)\n        \n    def forward(self, token_ids):\n        T = len(token_ids)\n        h0 = self.embed[token_ids]  # (T, d_model)\n        \n        # Sub-layer 1: Pre-RMSNorm + Causal Attention + Residual\n        norm_h0 = self.rms_norm(h0)\n        Q = np.dot(norm_h0, self.W_q.T)\n        K = np.dot(norm_h0, self.W_k.T)\n        V = np.dot(norm_h0, self.W_v.T)\n        \n        scores = np.dot(Q, K.T) / np.sqrt(self.d_model)\n        mask = np.triu(np.ones((T, T)), k=1)\n        scores = np.where(mask == 1, -1e9, scores)\n        attn = np.exp(scores - np.max(scores, axis=-1, keepdims=True))\n        attn /= np.sum(attn, axis=-1, keepdims=True)\n        attn_out = np.dot(np.dot(attn, V), self.W_o.T)\n        h1 = h0 + attn_out  # Residual connection\n        \n        # Sub-layer 2: Pre-RMSNorm + SwiGLU FFN + Residual\n        norm_h1 = self.rms_norm(h1)\n        gate = np.dot(norm_h1, self.W_gate.T)\n        up   = np.dot(norm_h1, self.W_up.T)\n        swish = gate * (1.0 / (1.0 + np.exp(-gate)))\n        ffn_out = np.dot(swish * up, self.W_down.T)\n        h2 = h1 + ffn_out  # Residual connection\n        \n        # Final Norm & Unembedding\n        final_norm = self.rms_norm(h2)\n        logits = np.dot(final_norm, self.W_u.T)  # (T, vocab_size)\n        return logits, attn\n\nmodel = MiniLLMDecoder(vocab_size=16, d_model=8, d_ff=21)\ninput_tokens = [2, 7, 11, 4]\nlogits, attn_matrix = model.forward(input_tokens)\n\nprint(f\"Input Token Sequence   : {input_tokens}\")\nprint(f\"Logits Output Shape    : {logits.shape} (T x Vocab)\")\nnext_token_pred = np.argmax(logits[-1])\nprint(f\"Prediksi Token Berikut : ID {next_token_pred} (Logit: {logits[-1, next_token_pred]:.4f})\")\nprint(\"Bobot Atensi Kausal Terakhir (Lower Triangular Valid):\\n\", np.round(attn_matrix, 3))",
